parameters.jsCode:
const raw = $input.first().json.choices[0].message.content.trim();

// Remove any leading = or labels like "Interviewer:"
const cleaned = raw
  .replace(/^=+/, '')
  .replace(/^\$json\.\S+/g, '')
  .replace(/^Interviewer:\s*/i, '')
  .trim();

return [{
  json: {
    next_question: cleaned
  }
}];
